mod certificate;use hec_native_ic::{counted,fp::Fp,poly::Poly,jac::Curve,instance::factor_base,rng::Rng};
fn main(){counted::disable();let(mut steps,mut fallback,mut shared,mut mutations)=(0,0,0,0);println!("p\tsm\tcase\trep\tkernel\tmodulus\tcounts");for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let target=c.mul(&d,k);let mut a=target;let mut fixtures=vec![];for _ in 0..16{let expected=c.add(&a,&d);let proof=certificate::build(&c,&a,&d);assert_eq!(proof.out,expected);assert!(c.is_valid(&a)&&c.is_valid(&d)&&c.is_valid(&proof.out));assert!(certificate::verify(&c,&a,&d,&proof));if proof.fallback{fallback+=1}steps+=1;let mut bad=proof.clone();bad.out.v=bad.out.v.add(&Poly::one(),&c.fp);assert!(!certificate::verify(&c,&a,&d,&bad));mutations+=1;if !proof.fallback{for field in 0..3{let mut bad=proof.clone();match field{0=>bad.w=bad.w.add(&Poly::one(),&c.fp),1=>bad.qa=bad.qa.add(&Poly::one(),&c.fp),_=>bad.qb=bad.qb.add(&Poly::one(),&c.fp)}assert!(!certificate::verify(&c,&a,&d,&bad));mutations+=1;}if proof.reduced{let mut bad=proof.clone();bad.gamma=0;assert!(!certificate::verify(&c,&a,&d,&bad));let mut bad=proof.clone();bad.qc=bad.qc.add(&Poly::one(),&c.fp);assert!(!certificate::verify(&c,&a,&d,&bad));mutations+=2;}}fixtures.push((a,proof));a=expected;}
let mut first=None;for rep in 0..2{let mut signature=vec![];for kernel in["native_verify","certificate_build","certificate_verify"]{counted::reset();for(a,proof)in &fixtures{match kernel{"native_verify"=>{assert_eq!(c.add(a,&d),proof.out);assert!(c.is_valid(&proof.out));},"certificate_build"=>{assert_eq!(format!("{:?}",certificate::build(&c,a,&d)),format!("{proof:?}"));},_=>assert!(certificate::verify(&c,a,&d,proof))}}let counts=counted::snapshot();counted::disable();for(m,v)in &counts{assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{kernel}\t{m}\t{}",v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}signature.push(counts);}if let Some(ref old)=first{assert_eq!(old,&signature)}else{first=Some(signature)}}}}for (a,b)in[(base,c.neg(&base)),(base,base),(c.zero(),base)]{let proof=certificate::build(&c,&a,&b);assert_eq!(proof.out,c.add(&a,&b));assert!(certificate::verify(&c,&a,&b,&proof));if proof.fallback{fallback+=1}else{shared+=1;}let mut bad=proof.clone();bad.out.v=bad.out.v.add(&Poly::one(),&c.fp);assert!(!certificate::verify(&c,&a,&b,&bad));mutations+=1;}}assert_eq!(steps,192);assert!(fallback>0&&shared>0);eprintln!("PASS original_chain_steps={steps} fallback_including_controls={fallback} shared_support_controls={shared} rejected_mutations={mutations} output_native_group_equal=true input_validity_precondition_explicit=true component_only=true independent_verification=false");}
